sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.searchQuery = '';
  c.selectedRecord = null;

  c.viewRecord = function(record) {
    c.loading = true;
    c.server.get({ action: 'getDetail', sys_id: record.sys_id }).then(function(r) {
      c.selectedRecord = r.data.selectedRecord;
      c.loading = false;
    }, function() {
      c.loading = false;
    });
  };

  c.closeDetail = function() {
    c.selectedRecord = null;
  };

  c.getSeverityClass = function(severity) {
    if (!severity) return 'label-default';
    var s = severity.toLowerCase();
    if (s === 'critical') return 'label-danger';
    if (s === 'high') return 'label-warning';
    if (s === 'medium') return 'label-info';
    if (s === 'low') return 'label-success';
    return 'label-default';
  };

  c.getStatusClass = function(status) {
    if (!status) return 'label-default';
    var s = status.toLowerCase();
    if (s === 'sent') return 'label-success';
    if (s === 'draft') return 'label-default';
    if (s === 'pending') return 'label-warning';
    if (s === 'failed') return 'label-danger';
    return 'label-default';
  };
};

sp_widget.css:
.sp-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-large;
  box-shadow: 0 1px 4px rgba($text-color, 0.07);
  background: $background-primary;
  overflow: hidden;
  margin-bottom: 0;
}
.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: $background-primary;
  border-bottom: 1px solid $border-tertiary;
  min-height: 52px;
  flex-shrink: 0;
}
.sp-card-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-card-icon {
  margin-right: 8px;
  color: $brand-primary;
  font-size: 16px;
}
.sp-card-body-flush {
  padding: 0;
  flex: 1 1 auto;
  overflow: hidden;
}
.sp-table-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: $background-secondary;
  border-bottom: 1px solid $border-tertiary;
  gap: 12px;
  flex-wrap: wrap;
}
.sp-search-box {
  position: relative;
}
.sp-search-icon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: $text-muted;
  font-size: 12px;
}
.sp-search-input {
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-base;
  height: 44px;
  width: 300px;
  padding: 0 10px 0 30px;
  font-size: $font-size-small;
  &:focus {
    border-color: $brand-primary;
    outline: none;
  }
}
.sp-th {
  font-size: 12px;
  font-weight: 600;
  color: $text-muted;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 12px 16px;
  border-bottom: 2px solid $border-tertiary;
  background: $background-secondary;
  white-space: nowrap;
}
.sp-td {
  font-size: $font-size-small;
  padding: 12px 16px;
  color: $text-color;
  border-bottom: 1px solid $border-tertiary;
  vertical-align: middle;
}
.sp-clickable-row {
  cursor: pointer;
  &:hover {
    background: $background-secondary;
  }
}
.sp-table-footer {
  padding: 8px 16px;
  font-size: 12px;
  color: $text-muted;
  border-top: 1px solid $border-tertiary;
  background: $background-secondary;
}
.sp-empty-state {
  padding: 64px 24px;
}
.sp-empty-icon {
  font-size: 48px;
  margin-bottom: 16px;
  display: block;
  opacity: 0.35;
  color: $text-muted;
}
.sp-empty-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin-bottom: 8px;
}
.sp-detail-panel {
  padding: 24px;
}
.sp-detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 8px;
}
.sp-detail-title {
  font-size: 22px;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-detail-body {
  dt {
    font-size: $font-size-small;
    color: $text-muted;
    margin-top: 12px;
  }
  dd {
    font-size: $font-size-base;
    color: $text-color;
    margin-left: 0;
    margin-bottom: 4px;
  }
}
.sp-detail-message {
  background: $background-secondary;
  padding: 12px 16px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  line-height: 1.6;
  margin-top: 4px;
}

sp_widget.script:
(function() {
  data.records = [];
  data.selectedRecord = null;

  try {
    if (input && input.action === 'getDetail') {
      var detail = new GlideRecord('x_1643968_bell_f_0_bell_flash');
      detail.setLimit(1);
      if (detail.get(input.sys_id)) {
        data.selectedRecord = {
          sys_id: detail.getUniqueValue(),
          number: detail.getValue('number') + '',
          short_description: detail.getValue('short_description') + '',
          flash_type: detail.getDisplayValue('flash_type') + '',
          flash_status: detail.getDisplayValue('flash_status') + '',
          severity: detail.getDisplayValue('severity') + '',
          notification_message: detail.getValue('notification_message') + '',
          nets_number: detail.getValue('nets_number') + '',
          recipient_group: detail.getDisplayValue('recipient_group') + '',
          recipient_user: detail.getDisplayValue('recipient_user') + '',
          sys_created_on: detail.getDisplayValue('sys_created_on') + ''
        };
      }
      return;
    }

    var gr = new GlideRecord('x_1643968_bell_f_0_bell_flash');
    gr.orderByDesc('sys_created_on');
    gr.setLimit(50);
    gr.query();
    while (gr.next()) {
      data.records.push({
        sys_id: gr.getUniqueValue(),
        number: gr.getValue('number') + '',
        short_description: gr.getValue('short_description') + '',
        flash_type: gr.getDisplayValue('flash_type') + '',
        flash_status: gr.getDisplayValue('flash_status') + '',
        severity: gr.getDisplayValue('severity') + '',
        sys_created_on: gr.getDisplayValue('sys_created_on') + ''
      });
    }
  } catch (e) {
    gs.error('bf_flash_record_list error: ' + e.message);
  }
})();
